export interface HandDrawnPathItem {
  id: string
  name: string
  category: 'highlight' | 'arrows' | 'shapes' | 'marks'
  icon: string
  pathD: string
  secondaryPathD?: string
  fillRule?: "nonzero" | "evenodd"
  viewBox: string
  defaultWidth: number
  defaultHeight: number
  defaultStrokeWidth: number
  defaultColor: string
  dna: VisualDNA
  tags: string[]
  description: string
}

