// ── SSOT: THÔNG SỐ & CÔNG THỨC DÙNG CHUNG CHO LAYER HAND-DRAWN ──
export const HAND_DRAWN_SPECS = {
  // 1. Thông số độ đậm nét (Stroke Width)
  defaultStrokeWidth: 4.5,
  minStrokeWidth: 1.5,
  maxStrokeWidth: 10,
  strokeStep: 0.5,

  // 2. Thông số thời gian vẽ (Animation Duration)
  defaultAnimDuration: 1.4,
  minAnimDuration: 0.3,
  maxAnimDuration: 3.0,
  animStep: 0.1,

  // 3. Màu sắc mặc định
  defaultAccent: '#BEFF01',
  defaultSecondaryColor: '#FFFFFF',

  // 4. Kích thước & Tọa độ mặc định
  defaultWidth: 150,
  defaultHeight: 100,
  defaultSpawnLeft: 180,
  defaultSpawnTop: 300,

  // 5. Hàm SSOT nhận diện nét đóng kín (Filled contour) vs nét đơn (Single stroke)
  isFilledPath: (fillRule?: string, pathD?: string): boolean => {
    return fillRule === 'evenodd' && Boolean(pathD && (pathD.includes('Z') || pathD.includes('z')));
  },

  // 6. Công thức SSOT tính độ nở viền khi kéo slider strokeWidth cho nét đóng
  calculateOutlineWidth: (strokeWidth?: number): number => {
    const sw = strokeWidth ?? 4.5;
    return Math.max(0, (sw - 3.5) * 1.2);
  },
} as const

