/**
 * Factory helper: Tạo đối tượng SceneElement từ Doodle Catalog ID chuẩn SSOT
 * Không bao giờ nhồi mã SVG thô trong template, tự động fallback an toàn
 */
export function createHandDrawnElement(
  catalogId: string,
  layout: { left: number; top: number; width?: number; height?: number; angle?: number },
  overrides?: Partial<SceneElement>
): SceneElement {
  const item = HAND_DRAWN_CATALOG.find((i) => i.id === catalogId);
  if (!item) {
    console.warn(`[HandDrawnCatalog] Cảnh báo: Không tìm thấy doodle item '${catalogId}', sử dụng fallback.`);
  }

  const defaultWidth = item?.defaultWidth ?? HAND_DRAWN_SPECS.defaultWidth;
  const defaultHeight = item?.defaultHeight ?? HAND_DRAWN_SPECS.defaultHeight;
  const defaultColor = item?.defaultColor ?? HAND_DRAWN_SPECS.defaultAccent;
  const strokeWidth = item?.defaultStrokeWidth ?? HAND_DRAWN_SPECS.defaultStrokeWidth;

  return {
    id: `hd-${catalogId}-${Date.now().toString(36)}`,
    type: 'hand-drawn',
    left: layout.left,
    top: layout.top,
    width: layout.width ?? defaultWidth,
    height: layout.height ?? defaultHeight,
    scaleX: 1,
    scaleY: 1,
    angle: layout.angle ?? 0,
    opacity: 1,
    stroke: overrides?.stroke ?? overrides?.color ?? defaultColor,
    strokeWidth: overrides?.strokeWidth ?? strokeWidth,
    accentColor: overrides?.accentColor ?? defaultColor,
    color: overrides?.color ?? defaultColor,
    svgContent: item?.pathD ?? '',
    secondarySvgContent: item?.secondaryPathD,
    fillRule: item?.fillRule,
    viewBox: item?.viewBox ?? `0 0 ${defaultWidth} ${defaultHeight}`,
    animPreset: overrides?.animPreset ?? 'none',
    animDelay: overrides?.animDelay ?? 0.2,
    animDuration: overrides?.animDuration ?? HAND_DRAWN_SPECS.defaultAnimDuration,
    ...overrides,
  };
}

